/* The Armv8 additions and optional extensions that are neither VFP nor
 * Advanced SIMD in the gadget engine's AArch32 builder. The gadgets are
 * generated by engine/a32_armv8.py, which documents the operand words this
 * file packs. */
#include "translator.hpp"

namespace uml::cpu::arm64::gadgets::a32::detail {

namespace {

[[nodiscard]] std::uint64_t core(int number) noexcept
{
	return static_cast<std::uint64_t>(number) * 8U;
}

} // namespace

Translator::Result Translator::emit_armv8(const Instruction &in,
					  const FormPlan &plan)
{
	const auto &o = in.operands;
	switch (plan.family) {
	case Family::crc:
		/* sub: bits 0-1 the size (byte, halfword, word), bit 2 CRC32C. */
		push(kCrc32[plan.sub >> 2][plan.sub & 3U]);
		push(core(o.d) | core(o.n) << 16 | core(o.m) << 32);
		return {};
	default:
		return {};
	}
}

} // namespace uml::cpu::arm64::gadgets::a32::detail
